import copy, hashlib, html, json, re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
SRC=Path('/workspace/shared/atlas-research/company-onboarding/ARM')
V2=SRC/'v2'
OUT=ROOT/'dist/data/incremental-ARM-2026-10-19-v2'
OUT.mkdir(parents=True,exist_ok=True)
BASE='./data/'+OUT.name+'/'
def read(path): return json.loads(path.read_text())
def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def write(name,data):
 p=OUT/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(data,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
def cleantext(s):
 s=s.replace(str(SRC)+'/','').replace(str(SRC),'ARM research archive')
 return re.sub(r'(?:/workspace/|/home/|/tmp/|file://)[^\s\"\'<>`]+','[private execution path omitted]',s)
def clean(x):
 if isinstance(x,dict): return {k:clean(v) for k,v in x.items()}
 if isinstance(x,list): return [clean(v) for v in x]
 return cleantext(x) if isinstance(x,str) else x
inputs=read(V2/'dcf-inputs-v2.json');outputs=read(V2/'dcf-output-v2.json')
audit=read(SRC/'independent-audit-v1/v2-model-results.json');review=(SRC/'independent-audit-v1/REVIEW.md').read_text()
assert 'PASS: admit the v2 package' in review and audit['shipped_tests']=='119 checks passed'
assert inputs['capital']['ordinary_shares']==1064.055252 and inputs['capital']['ads_per_ordinary']==1
assert all(len(o['rows'])==10 and not o['funding_required'] for o in outputs.values())
for n,expected in {'bear':8.475119054202718,'base':25.463301826575428,'bull':62.42269730253597}.items(): assert abs(outputs[n]['value_per_ads']-expected)<1e-12
# Verify the source freeze before copying only research-derived artifacts.
source_manifest=read(V2/'integrity-manifest-v2.json')
for name,item in source_manifest['files'].items(): assert sha(V2/name)==item['sha256'],name
allowed=['STUDY-v2.md','dcf-inputs-v2.json','dcf-output-v2.json','forecast-v2.csv','guidance-vs-actual-v2.csv','guidance-vs-actual-v2.json','history-field-provenance-v2.json','history-v2.csv','history-v2.json','integrity-manifest-v2.json','replay_dcf.py','sensitivities-v2.json','source-ledger-v2.json','test_v2.py','validation-v2.json','v1-preservation-check.json']
manifest=[]
for rel,source in [(name,V2/name) for name in allowed]+[(name,SRC/name) for name in ['dcf-output-v1.json','legacy-history-noncomparable-v1.json','source-ledger-v1.json','html-sources.json','audit-additional-sources-v1.json','independent-audit-v1/REVIEW.md','independent-audit-v1/history-guidance-review.md','independent-audit-v1/v2-model-results.json']]:
 dest=OUT/rel;dest.parent.mkdir(parents=True,exist_ok=True)
 content=cleantext(source.read_text())
 if rel=='test_v2.py':content=content.replace("p.parent/'dcf-output-v1.json'", "p/'dcf-output-v1.json'")
 dest.write_text(content)
 manifest.append({'sourceArtifact':source.relative_to(SRC).as_posix(),'packagedArtifact':rel,'sourceSHA256':sha(source),'packagedSHA256':sha(dest)})
write('conditional-outputs-v2.json',outputs)
raw_history=read(V2/'history-v2.json');provenance=read(V2/'history-field-provenance-v2.json');legacy=read(SRC/'legacy-history-noncomparable-v1.json')
legacy_by_year={r['fiscal_year_ended_march31']:r for r in legacy}
history=[]
for raw in raw_history:
 fy=raw['fiscal_year'];comparable=fy>=2021;old=legacy_by_year.get(fy)
 fp=[copy.deepcopy(p) for p in provenance if p['fiscal_year']==fy]
 if not comparable:
  fp=[{'fiscal_year':fy,'field':k,'value':old[k],'unit':'USD millions','source':old['source'],'locator':'SoftBank Arm segment USD reference table','basis':old['basis']} for k in ['revenue','licensing','royalty','software_services']]
 note=(raw.get('scope_note','')+' '+raw.get('cash_scope','')+' '+raw.get('ppe_presentation_note','')+' '+raw.get('shares_missing_note','')+' '+raw.get('shares_precision_note','')).strip() if comparable else old['basis']+'; no comparable standalone EBIT or cash flow.'
 notezh=('收入及营业利润为持续经营；2021–2022 净利润／现金流／折旧／股权薪酬口径可能包含终止业务。股数精度随来源变化。'+('2021 现金 1,171 仅持续经营，合并现金 1,214 含终止业务 43。' if fy==2021 else '')+('2022 普通股期末数未核实，保留空值。' if fy==2022 else '')+('2025 比较口径 PPE 354 排除另列融资租赁资产 40，原呈报合计 394。' if fy==2025 else '')) if comparable else '软银 Arm 分部美元历史参考，范围及会计不可比；2017 为收购前后备考数据。不可拼接成十年可比增长序列。'
 url=('https://investors.arm.com/node/6546/html' if fy<=2023 else 'https://www.sec.gov/Archives/edgar/data/1973239/000197323924000012/arm-20240331.htm' if fy==2024 else 'https://investors.arm.com/node/8281/html') if comparable else old['source']
 h={'period':f'FY{fy}','fiscalYear':fy,'fiscalEnd':f'{fy}-03-31','periodStart':raw.get('period_start'),'revenue':raw.get('revenue') if comparable else old['revenue'],'canonicalOperatingEBIT':raw.get('operating_income'),'operatingMargin':raw.get('operating_margin'),'grossProfit':raw.get('gross_profit'),'cashFromOperations':raw.get('cfo'),'ownCapex':raw.get('capex'),'DA':raw.get('da'),'SBC':raw.get('sbc'),'reportedOrDerivedFCFIncludingIntangibles':raw.get('derived_fcf_including_intangibles'),'comparableIssuerAnnual':comparable,'coverage':raw['coverage'] if comparable else 'legacy_noncomparable_SoftBank_segment','basisLabel':'Comparable/reconstructed US-GAAP' if comparable else 'Noncomparable SoftBank legacy segment','basisLabelZh':'可比／重建美国会计准则' if comparable else '不可比软银历史分部','classification':note,'classificationZh':notezh,'comparability':note,'sourceUrl':url,'fieldProvenance':clean(fp),'sourceRow':copy.deepcopy(raw)}
 if old:h['legacySourceRow']=copy.deepcopy(old)
 history.append(h)
write('history-normalized-v2.json',history)
guidance=[]
for r in read(V2/'guidance-vs-actual-v2.json'):
 r=copy.deepcopy(r);r['status']='observed';r['guide_url']=r['forecast_source'];r['actual_url']=r['actual_source'];r['guidance_date']=r['forecast_issued_date'];r['target_period']=r['quarter']
 r['fieldProvenance']={k:{'source':r['forecast_source'] if ('low' in k or 'high' in k or 'guidance' in k) else r['actual_source'],'issuedDate':r['forecast_issued_date'] if ('low' in k or 'high' in k or 'guidance' in k) else r['actual_issued_date'],'locator':r['locator'],'basis':('non-GAAP approximate estimate, not a hard range' if 'guidance' in k else 'non-GAAP actual operating expenses') if 'opex' in k else 'non-GAAP EPS' if 'eps' in k else 'reported revenue; USD millions'} for k in ['revenue_low','revenue_high','revenue_actual','non_gaap_eps_low','non_gaap_eps_high','non_gaap_eps_actual','non_gaap_opex_approx_guidance','non_gaap_opex_actual']}
 guidance.append(r)
write('guidance-comparisons-v2.json',guidance)
A='https://investors.arm.com/node/8281/html';Q='https://investors.arm.com/node/8361/html';L='https://investors.arm.com/node/8356/html';IPO='https://investors.arm.com/node/6546/html'
# Complete bilingual analysis: concise synthesis plus full original English study below.
pairs={
'summary':('Arm monetizes processor architecture and IP through licenses and per-chip royalties. Moving into production silicon creates a separate capital, inventory and margin model. Conditional bear/base/bull values are $8.4751/$25.4633/$62.4227 per ADS, with about 74%/78%/83% of enterprise value in terminal cash flows. No probabilities, current stock quote, upside or recommendation is supplied.','Arm 通过处理器架构及设计授权、逐芯片版税变现。进入量产芯片业务会引入独立的资本、库存与利润模型。有条件熊／基准／牛情景为每 ADS 8.4751／25.4633／62.4227 美元，终值约占企业价值 74%／78%／83%。没有赋予概率、引用当前股价、计算上涨空间或提出投资建议。'),
'scope':('March 31, 2026 is the capital and discount origin; information extends to October 19, 2026. Ten FY2027–36 annual cash flows use year-end discounting; FY2037 is terminal. This is a restated-date conditional appraisal, neither a historical backtest nor an October 19 current valuation. Current value, target, upside and ranking gates remain false even if a quote is entered. Current cash, exact shares, obligations and a stub must be independently refreshed first.','资本与折现起点为 2026 年三月三十一日，信息截至十月十九日。2027–2036 十个财年现金流按年末折现，2037 为终值年。这是带后续信息的指定日期条件估值，不是历史回测或十月十九日当前估值。即使输入股价，当前估值、目标价、上涨空间及排名资格仍关闭；须先独立刷新现金、精确股数、义务及期间现金流。'),
'business':('FY2026 revenue $4,920m comprises royalty $2,613m (53.1%) and license/other $2,307m (46.9%). FY2025 was $2,168m/$1,839m and FY2024 $1,802m/$1,431m. License recognition depends on delivery, renewals, service and contract timing; royalties depend on customers’ shipments, reporting, mix and rates. Armv9 and compute subsystems can lift royalties per chip, but AI spending is not automatically Arm revenue. Architecture/software switching costs and long design cycles coexist with RISC-V, x86, custom designs and customer bargaining power. Contract-level rates and a complete audited end-market profit split are unavailable.','2026 财年收入 4,920 百万美元，其中版税 2,613（53.1%）、授权及其他 2,307（46.9%）；2025 对应为 2,168／1,839，2024 为 1,802／1,431。授权确认受交付、续约、服务及合同时点影响；版税取决于客户出货、申报、组合及费率。Armv9 与计算子系统可提高单芯片变现，但 AI 支出不会自动转成 Arm 收入。架构与软件转换成本、长设计周期，与 RISC-V、x86、自研方案及客户议价并存。缺乏合同级费率及完整审计终端市场利润分解。'),
'recentQuarter':('FY2027 Q1 revenue was $1,289m: $715m royalty and $574m license/other. ACV $1,732m grew 13% versus revenue growth 22%; ACV is not recognized licensing revenue. Management said data-center royalties more than doubled. GAAP EBIT $91m (7.1%) contrasts with non-GAAP EBIT $531m (41.2%), making exclusions and employee equity economically important. Quarterly collections and cash flow are not annualized.','2027 财年第一季收入 1,289 百万美元：版税 715、授权及其他 574。年化合同价值 ACV 为 1,732、增长 13%，收入增长 22%；ACV 不等于已确认授权收入。管理层称数据中心版税翻倍以上。GAAP 营业利润 91（7.1%）与非 GAAP 531（41.2%）差距显著，排除项目及员工股权的经济成本不可忽略。季度收款及现金流不作简单年化。'),
'silicon':('AGI CPU was announced in March 2026 with no material FY2026 revenue effect. July management said initial products reached multiple customers and capacity covered the original $1bn FY2027–28 opportunity, while demand exceeded $2bn. Demand/pipeline is not booked revenue, audited backlog, take-or-pay commitment or secured $2bn capacity. The July call describes $193m quarterly SoftBank technology/design-service revenue and an approximately $200m quarterly run-rate expectation, both management statements. September Neoverse CSS N4/Volcano Engine news is qualitative validation, not quantified extra orders.','AGI CPU 于 2026 年三月公布，对 2026 财年收入无重大影响。七月管理层称已向多个客户交付初始产品，产能覆盖最初 2027–2028 财年 10 亿美元机会，而需求超过 20 亿。需求／管线并非已入账收入、审计积压订单、照付不议承诺或已保障 20 亿美元产能。七月电话会称软银技术／设计服务季度贡献 193 百万美元，其余季度预计约 200，均为管理层表述。九月 Neoverse CSS N4／火山引擎消息仅为定性验证，不是新增可量化订单。'),
'competition':('Production silicon increases value per deployment but can compete with IP licensees. Qualification, wafer/packaging/test, supply concentration, yields, warranty, cancellation, inventory and collections become material. Annual disclosure includes about $100m near-term semiconductor supply purchase commitments and $1,056.5m cloud/data-center/software/service obligations through 2036. They overlap future operating costs/investment and are not automatically additional debt. The research has no physical capacity, yield or unit-cost validation.','量产芯片可提高每次部署价值，也可能与 IP 被授权客户竞争。认证、晶圆／封装／测试、供应集中、良率、保修、取消订单、库存及收款均重要。年报披露约 100 百万美元近期半导体采购承诺及截至 2036 年约 1,056.5 百万美元云／数据中心／软件／服务义务。其与未来经营成本和投资重叠，不自动加作债务。本研究未完成物理产能、良率或单位成本验证。'),
'guidance':('All nine quarters Q1 FY2025–Q1 FY2027 retain separate forecast and actual publication dates, public source links and field provenance. Revenue exceeded range in four quarters and non-GAAP EPS in five; neither missed below range. Approximate non-GAAP opex estimates are not hard guidance bands. FY2025 initial revenue guidance $3.8–4.1bn narrowed to $3.94–4.04bn; actual $4.007bn and non-GAAP EPS $1.63 fell within final ranges. This supports cautious short-term execution, not a calibrated decade-long management premium or probability distribution.','2025 第一季至 2027 第一季全部九组季度记录保留指引与实际发布日期、公开来源及字段来源。四季收入、五季非 GAAP 每股收益超过区间，没有低于下限。近似非 GAAP 费用估计不是硬性区间。2025 年收入最初指引 38–41 亿美元，后收窄至 39.4–40.4 亿；实际 40.07 亿及非 GAAP 每股收益 1.63 均在最终区间内。这支持谨慎短期指引及执行判断，不构成十年管理层溢价或已校准概率分布。'),
'profitability':('FY2026 sales rose 22.8%, but GAAP EBIT rose 8.3% and margin fell from 20.7% to 18.3%. R&D increased from $2,071m to $2,776m, about 34%. Investment-led growth is plausible; immediate operating leverage is not established. Executive incentives use non-GAAP financial metrics, so owner economics must retain compensation and examine collection quality.','2026 财年收入增长 22.8%，GAAP 营业利润仅增长 8.3%，利润率由 20.7% 降至 18.3%。研发由 2,071 增至 2,776 百万美元，约增长 34%。可解释为投资驱动增长，但未证明即时经营杠杆。高管激励使用非 GAAP 财务指标，股东经济回报必须保留薪酬成本并检验收款质量。'),
'china':('Arm China is not controlled by Arm or SoftBank. Arm holds a 10% nonvoting Acetone interest; Acetone holds 48.2% of Arm China, giving about 4.8% indirect economics, not 48.2% consolidation. Arm China FY2026 revenue $790.6m (16.1%) compares with $670.4m/$670.8m in FY2025/24. Service-share costs were $63.3m, net amounts due $276.2m and credit-loss allowance $28.3m. Arm China concentration differs from all PRC geography; reporting/access and collections remain risks.','Arm 中国不受 Arm 或软银控制。Arm 持有 Acetone 10% 无投票权权益，后者持有 Arm 中国 48.2%，间接经济权益约 4.8%，并非合并持有 48.2%。Arm 中国 2026 收入 790.6 百万美元（16.1%），2025／2024 为 670.4／670.8；服务分成成本 63.3、应收净额 276.2、信用损失准备 28.3。Arm 中国集中度不同于全部中国地域收入，申报／访问及收款风险仍存在。'),
'relatedParties':('Related-party revenue $1,499m was 30.5% of FY2026 sales versus $823m prior year; external sales grew 7%, related-party sales 82%. The SoftBank-affiliate technology/service arrangement contributed $704.4m revenue and $645.8m current contract assets. Earned-but-not-yet-billable contract assets are not cash. Do not add Arm China to total related-party exposure again. A strong case requires external demand and eventual billing/collection, not merely bigger intragroup commitments.','2026 关联方收入 1,499 百万美元、占 30.5%，上年为 823；外部客户增长 7%，关联方增长 82%。软银关联技术／服务安排贡献收入 704.4、流动合同资产 645.8。已赚取但尚未可开票的合同资产不是现金，不可再把 Arm 中国收入加到关联方总额。强情景需要外部需求及最终开票收款，不能仅靠集团内承诺增加。'),
'governance':('SoftBank owned 922,733,999 shares, about 86.4%, on May 21, when ordinary shares totaled 1,068,078,760; September offering materials report 86.4% at June 30. The remaining roughly 14% is not verified freely trading float. Control affects related-party deals, directors, acquisitions and monetization. SoftBank’s September-expanded $25bn Arm-share-backed financing is SoftBank debt, not Arm corporate debt. Low effective float affects trading, not enterprise cash flows.','五月二十一日普通股共 1,068,078,760 股，软银持有 922,733,999 股、约 86.4%；九月融资文件报告六月底仍为 86.4%。剩余约 14% 并非已核实自由流通股。控制权影响关联交易、董事、收购及资产变现。软银九月扩大至 250 亿美元的 Arm 股份抵押融资是软银债务，不是 Arm 公司债务。低有效流通量影响交易，而非企业现金流。'),
'litigation':('Arm’s October 13 account says the jury found for Arm on four Qualcomm claims and awarded Qualcomm $1 on each of two other claims. Attribution and the limited verdict scope matter: this does not establish that every dispute, appeal or commercial consequence is resolved. No litigation-win revenue uplift is modeled.','Arm 十月十三日声明称，陪审团在高通四项主张上支持 Arm，并在另两项各判高通获赔 1 美元。须保留来源归属及判决范围，不能据此称所有纠纷、上诉或商业后果已经结束。模型没有添加胜诉收入增量。'),
'acquisition':('The full June-quarter 6-K says DreamBig closed July 1 for about $265m cash. The March 31 bridge reserves nominal $265m immediately, without discounting the later outflow. This is a conservative analyst reserve, not exact transaction present value. Acquired cash/liabilities and final adjustments are not separately modeled; it is not pending, is not charged again as forecast investment, and receives no independent synergy value.','完整六月季度 6-K 称 DreamBig 于七月一日完成、现金价约 265 百万美元。三月三十一日桥接立即预留名义金额 265，不折现较晚现金流。这是保守分析预留，不是精确交易现值。未分别建模被收购现金／负债及最终调整；不将其视为待完成，不在未来投资重复扣除，也不另加协同价值。'),
'history':('Ten FY2017–26 slots contain six comparable/reconstructed US-GAAP annual periods FY2021–26 and four explicitly separate noncomparable SoftBank segment revenue years. Legacy totals are $1,689m/$1,831m/$1,836m/$1,898m; FY2017 is pro forma. Software/services scope, China deconsolidation, acquisitions and accounting differ. No ten-year comparable CAGR is inferred. All six annual rows preserve detailed source observations and 160 provenance entries; FY2022 receivables $1,124m and PPE $188m are filled, but outstanding shares remain null.','2017–2026 十个年度位置包含六个 2021–2026 可比／重建美国会计准则年度，以及四个明确分开的不可比软银分部收入年度。旧收入为 1,689／1,831／1,836／1,898 百万美元；2017 为备考。软件／服务范围、中国业务移出合并、收购及会计不同，不推导十年可比复合增长率。六年保留详细原始观察及 160 条字段来源；2022 应收 1,124、PPE 188 已补齐，但期末股数仍为空。'),
'historyLimits':('FY2021 continuing net income $544m versus consolidated $388m includes $156m discontinued loss; FY2022 $676m versus $549m includes $127m loss. CFO/D&A/SBC can include discontinued activity. FY2021 cash $1,171m is continuing-only versus consolidated $1,214m, including $43m discontinued cash; CFO benefited from a one-time $750m customer prepayment. IPO award acceleration and cash/equity compensation changes break naive SBC comparability. FY2025 PPE $354m excludes separately presented $40m finance-lease assets versus original combined $394m. EPS shares mix exact/rounded vintages; rounding must not imply tiny real dilution.','2021 持续经营净利 544、合并净利 388 含终止业务亏损 156；2022 为 676／549、亏损 127。现金流／折旧／股权薪酬可能包含终止业务。2021 现金 1,171 仅持续经营，合并 1,214 含终止业务 43；经营现金流受一次性客户预付 750 支持。IPO 奖励加速确认及现金／股权薪酬变化妨碍简单趋势比较。2025 PPE 354 排除单列融资租赁资产 40，原合计 394。EPS 股数混合精确与四舍五入来源，不能由舍入推导微小真实稀释。'),
'cashConversion':('FY2026 CFO $1,524m less PPE cash capex $545m is $979m, not issuer-reported FCF. Subtract $30m intangible purchases and $67m intangible obligations to reach $882m, versus FY2025 $99m. CFO adds back SBC $1,052m; vested-award withholding consumed $529m in financing. Q1 FY2027 CFO $902m minus PPE $197m, intangibles $11m and obligations $29m gives $665m FCF, with $278m financing withholding. These figures are not recurring unlevered owner FCFF.','2026 经营现金流 1,524 减 PPE 现金开支 545 得 979 百万美元，并非公司报告自由现金流。再减无形资产购置 30 及无形义务付款 67 得 882，2025 为 99。经营现金流加回股权薪酬 1,052，已归属奖励代扣税在融资项耗资 529。2027 第一季 902 减 PPE 197、无形资产 11、义务 29 得 FCF 665，融资代扣 278。这些不等于可重复无杠杆股东 FCFF。'),
'bridge':('March 31 cash plus short investments $3,601m minus finance leases $59m, existing EDA liabilities $175m ($78m current/$97m noncurrent), DreamBig reserve $265m and minimum operating cash $246m yields $2,856m. All $387m equity investments receive zero bridge value: $96m quoted and $291m other holdings. Exclusion is conservative, not a claim all are illiquid or in cash. Operating leases $432m are not separately deducted because rent remains expensed. Future productive investment covers tangible/intangible assets; no double deduction of the opening EDA claim.','三月三十一日现金及短期投资 3,601，减融资租赁 59、既有 EDA 义务 175（流动 78／非流动 97）、DreamBig 预留 265、最低经营现金 246，桥接净额 2,856 百万美元。全部股权投资 387 在桥接中计零，含上市持股 96 及其他 291。此为保守排除，不代表全部缺乏流动性或包含于现金。经营租赁 432 不另扣，因为租金仍费用化。未来生产性投资覆盖有形与无形资产，期初 EDA 请求权不重复扣除。'),
'awards':('Exactly 1,064,055,252 March 31 ordinary shares equal 1,064.055252m ADS at 1:1. This is neither diluted EPS weighted-average 1,068m nor a market-cap proxy. June ordinary shares 1,068m are rounded; quarterly diluted average 1,078m is not point-in-time capital. March awards approximate 1m 2022-plan RSUs plus 18m Omnibus awards; June Omnibus rose to 24m. Ungranted PSUs are excluded. June unrecognized Omnibus compensation $3,621.9m/1.6 years compares with March $1,719.3m/1.2 years. The 425,000 VCP PSUs are already included; plan headroom is not issued dilution.','三月三十一日精确普通股为 1,064,055,252，按 1:1 等于 1,064.055252 百万 ADS。不同于稀释 EPS 加权平均 1,068 百万，也非市值代理。六月普通股 1,068 百万为舍入，季度稀释平均 1,078 不是时点股本。三月奖励约为 2022 计划 RSU 1 百万及 Omnibus 18 百万；六月 Omnibus 升至 24 百万，未定授予日 PSU 不含在内。六月未确认薪酬 3,621.9／1.6 年，三月 1,719.3／1.2 年。425,000 VCP PSU 已包含，不可再加；计划额度不是已发行稀释。'),
'sbc':('Baseline margins charge cash-equivalent economic SBC and expense R&D, with fixed March shares. This replacement-compensation convention is not exact legal allocation among shares and awards, or a claim of no real future dilution. Economic margin shocks of −5pp/−10pp/+5pp and a separate 19m extra-share denominator expose risk. The share diagnostic may overlap already charged compensation, omits ungranted PSUs and is not a maximum dilution bound. Precise claims require grant-level fair value/vesting. Treasury is economic replacement cash, not a GAAP cash forecast.','基准利润率扣除现金等价经济股权薪酬，研发费用化，股数固定为三月数。这是替代薪酬约定，不是股份与奖励的精确法律分配，也不声称现实中无未来稀释。经济利润率 −5／−10／+5 个百分点及另加 19 百万股分母诊断展示风险。股数诊断可能与已扣薪酬重叠、遗漏未定授予 PSU，不能视为最大稀释界限。精确请求权需逐笔授予估值／归属模型；资金模型是经济替代现金，而非 GAAP 现金预测。'),
'growth':('FY2027–36 royalty growth starts at 14%/24%/32%, license growth 2%/10%/15%, and converges to 2.5%/3%/3.5%. Silicon is an explicit revenue path, not fabricated growth from zero; FY2027–28 totals $350m/$1,000m/$1,800m. Mature IP EBIT margins are 22%/34%/42% and silicon 10%/20%/27%, inclusive of SBC and R&D. Base uses the original $1bn opportunity; bull needs extra supply and execution. No own-silicon royalty is double counted. Every forecast path is an analyst assumption, not management annual guidance.','2027–2036 版税首年增长 14%／24%／32%，授权增长 2%／10%／15%，逐年收敛至 2.5%／3%／3.5%。芯片采用明确收入路径，不虚构零基数增长；2027–2028 合计 350／1,000／1,800 百万美元。成熟 IP 营业利润率 22%／34%／42%，芯片 10%／20%／27%，均已扣股权薪酬和研发。基准取原 10 亿机会，牛情景需额外供给与执行；不对自有芯片重复计算版税。全部预测是分析假设，不是管理层全年指引。'),
'capital':('Incremental NWC is 20% of IP revenue change plus 30% of silicon change and changes in a 5%-of-sales operating cash reserve. Net productive investment includes tangible and intangible assets, unlike gross GAAP capex. Initial net-capex intensities 6.5%/7.5%/9% decline; final three years blend to NOPAT×g/ROIC less NWC. Positive 2.5% net investment floors apply to total and both segments every year and terminal. These are analyst constraints, not proven physical engineering, maintenance capex or capacity estimates. Inconsistent residual investment is invalid/null, never clipped while retaining incompatible ROIC.','增量营运资本为 IP 收入变化的 20% 加芯片变化的 30%，再加销售额 5% 经营现金储备的变化。净生产性投资包括有形及无形资产，区别于 GAAP 总资本开支。初始净投资强度 6.5%／7.5%／9% 逐步下降，最后三年过渡至 NOPAT×增长／ROIC 减营运资本。每年及终值对总额和两业务均执行正的 2.5% 净投资底线。这是分析约束，不是已证实物理工程、维持性开支或产能估计。残余投资不一致则无效／空值，不能加高投资同时保留矛盾 ROIC。'),
'wacc':('Bear/base/bull WACC is 11.5%/10%/9%, terminal growth 2.5%/3%/3.5%, terminal incremental ROIC 12%/18%/24% and normalized tax 23%. These choices reflect scenario risk, not fitted current market beta/rates. Losses receive no immediate refund. Growth must be below both WACC and ROIC, and all inputs must satisfy finite/domain checks. EPS and market stock price never calibrate the model.','熊／基准／牛 WACC 为 11.5%／10%／9%，终值增长 2.5%／3%／3.5%，终值增量 ROIC 12%／18%／24%，正常化税率 23%。这些是情景风险选择，不是当前市场贝塔／利率拟合。亏损无即时退税。增长须低于 WACC 和 ROIC，全部输入须通过有限值／取值域校验；不用 EPS 或市场股价反推模型。'),
'funding':('Treasury starts after finance-lease/EDA settlements and the acquisition reserve, retains cash and pays interest while testing the annual 5% sales floor. Incremental operating cash reduces FCFF but remains available treasury cash. Deficits borrow up to 1.5×positive EBIT capacity, then issue at a hypothetical $50/ADS with 3% fees. These are not lending commitments or observed prices. Baselines need no funding. External-funded cases suppress headline per-ADS value; the denominator-only diagnostic is not financing-adjusted fair value. No repurchases, dividends or speculative acquisitions are assumed.','资金从扣融资租赁／EDA 清偿及收购预留后开始，保留现金并支付利息，逐年检查销售额 5% 现金底线。增量经营现金扣减 FCFF 但留在资金池。缺口先借款至正 EBIT 的 1.5 倍容量，再以假设每 ADS 50 美元、3% 费用发行股权。这不是贷款承诺或实际发行价。基准路径均无需融资；需要外部融资的路径不提供主要每 ADS 估值，单纯分母诊断不是融资调整后公允价值。没有假设回购、分红或投机收购。'),
 'terminal':('Final reinvestment equals NOPAT×g/ROIC. Final IP growth equals g; silicon must equal prior-year silicon×(1+g), including a zero base: both-zero is valid and zero-to-positive is rejected. Terminal net investment must meet the positive analyst floor; growth is not free. V2 preserves all three baselines while five 2%-growth sensitivity cells and two negative-SBC-margin shocks become invalid/null. Sensitivity rejection is meaningful, not a missing price to fill. High terminal shares make long-run profitability and investment especially consequential.','最终再投资等于 NOPAT×增长／ROIC。最后 IP 增长等于终值增长，芯片收入必须等于上年×（1+增长），零基数也适用：两年均零有效，零跃升正值拒绝。终值净投资须满足正分析底线，增长并非免费。v2 保留三种基准输出，但五个 2% 增长敏感性及两个负股权薪酬利润率冲击变为无效／空值。拒绝有经济含义，不是待填的价格；高终值占比使长期利润与投资尤其重要。'),
'uncertainty':('Named cases have no calibrated probabilities. Parameter simulations must not imply an estimated return distribution or repair invalid investment/funding with fabricated values. Each trial must recompute growth, terminal floor and treasury; invalid/funded headline cases remain visible exclusions. The compact annual editor uses the chosen segment mix, not a physically validated chip forecast. Wider capital, cash, award and manufacturing evidence is required before a current target.','命名情景没有已校准概率。参数模拟不得暗示已估计收益分布，或用虚构数值修复无效投资／融资。每次试验都须重算增长、终值底线与资金；无效及需融资的主要估值应明确排除。简要年度编辑器使用选定情景业务组合，不是经物理验证的芯片预测。当前目标价前还需更完整资本、现金、奖励与制造证据。'),
'audit':('Final independent v2 disposition admits a dated analyst-constrained research exhibit. Independent arithmetic replay preserves bear/base/bull outputs; the shipped v2 suite passed 119 checks. The 23-file v2 source manifest and 70 original v1 entries remained unchanged at review. Final corrections fill two FY2022 cells, clarify PPE/cash/share precision, separate guidance dates and ledger the Q4 FY2025 letter and two frozen legacy PDFs. Earlier editable-model HOLD in the retained audit is superseded only for v2. Research approval does not certify this adapter, physical economics or deployment.','最终独立 v2 结论允许作为指定日期、分析约束研究展示。独立算术复演保留熊／基准／牛输出，v2 测试通过 119 项；复核时 v2 的 23 个清单文件及原 v1 的 70 项均未改变。最终修正补齐 2022 两字段，澄清 PPE／现金／股数精度，区分指引日期，并将 2025 第四季信及两份已冻结旧年度 PDF 纳入来源。保留审查中的早期可编辑模型暂缓仅对 v2 被取代。研究批准不认证本适配器、物理经济或部署。'),
'publicationGates':('Watch recognized and collected AGI revenue, paid capacity, yields, margins, cancellation terms and customer concentration. Separate unrelated royalty/license growth from SoftBank contract-asset billing and Arm China collections. Reconcile award costs/taxes after June expansion. At cutoff, results page lists November 4 for Q2 FY2027; the September quarter is not fabricated. Refresh capital/exact shares/stub before current-price use; verify a full accounting bridge before ten-year comparability. No probability-weighted target without justified probabilities.','观察 AGI 已确认及已收款收入、已支付产能、良率、利润率、取消条款及客户集中。将独立客户版税／授权增长与软银合同资产开票、Arm 中国收款分开。六月奖励扩大后重新对账薪酬及税。截止时结果页列 11 月 4 日为 2027 第二季发布，不虚构九月季度。当前股价比较前刷新资本／精确股数／期间现金流，十年可比前核实完整会计桥接；没有合理概率便不提供概率加权目标。')}
prose={k:{'en':v[0],'zh-Hans':v[1]} for k,v in pairs.items()}
