# Flatten source ledgers without copying the linked corporate originals.
def flatten(x):
 if isinstance(x,list):
  for v in x:yield from flatten(v)
 elif isinstance(x,dict):
  if x.get('url'):yield x
  for k in ('content','sources'):
   if k in x:yield from flatten(x[k])
