for source in list(flatten(read(SRC/'source-ledger-v1.json')))+list(flatten(read(V2/'source-ledger-v2.json'))):
 if source['url'] in seen:continue
 seen.add(source['url']);s=copy.deepcopy(source);s['id']=s.get('file',s['url']);s['retrieved']=s.get('retrieved_utc',s.get('retrieved_or_verified',s.get('retrieved','2026-10-19')));s['evidence']='Primary public source; original document linked, not redistributed'
 if not s.get('sha256'):
  f=V2/s['file'] if (V2/s['file']).is_file() else SRC/s['file']
  if f.is_file():s['sha256']=sha(f)
 sources.append(s)
